 void settings(){LinearLayout l=page("Settings");heading(l,"Account");item(l,"Account details",DemoSession.email,null,()->launch(ProfileActivity.class));heading(l,"Profile");item(l,"Edit profile","Update personal and academic information",null,()->launch(ProfileWizardActivity.class));heading(l,"Appearance");Switch theme=new Switch(this);theme.setText("Dark theme preference");theme.setChecked(getPreferences(0).getBoolean("dark",false));theme.setOnCheckedChangeListener((b,c)->{getPreferences(0).edit().putBoolean("dark",c).apply();toast("Preference saved. This presentation build uses the light institutional theme.");});l.addView(theme);l.addView(text("Light mode is the supported presentation theme.",12,muted,false));heading(l,"Notifications");Switch notif=new Switch(this);notif.setText("Placement notifications");notif.setChecked(true);l.addView(notif);heading(l,"Help and support");item(l,"Placement & Training Department","Contact your college placement cell",null,()->toast("Contact your college placement cell"));heading(l,"About");item(l,"NMIMS Hyderabad Placement Portal","Student Career & Placement Management System",null,()->toast("PlaceMate demonstration build"));item(l,"Privacy information","Local demo profile data stays in this session.",null,null);heading(l,"Session");action(l,"Log out",this::logout);}
